CREATE TABLE "media_comments" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "media_comment" TEXT COLLATE NOCASE NOT NULL, "media_id" INTEGER NOT NULL, "date" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "media_entries" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "title" TEXT COLLATE NOCASE NOT NULL, "description" TEXT COLLATE NOCASE NOT NULL, "filename_final" TEXT COLLATE NOCASE NOT NULL, "filename_original_name" TEXT COLLATE NOCASE NOT NULL, "filename_ext" TEXT COLLATE NOCASE NOT NULL, "hash" TEXT COLLATE NOCASE NOT NULL, "similar_hash" TEXT COLLATE NOCASE NOT NULL, "upload_time" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "media_list_of_tags" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "tag_name" TEXT COLLATE NOCASE NOT NULL, "description" TEXT COLLATE NOCASE NOT NULL);

CREATE TABLE "media_ratings" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "rating" INTEGER NOT NULL, "media_id" INTEGER NOT NULL);

CREATE TABLE "media_tag" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "media_id" INTEGER NOT NULL, "tag_id" INTEGER NOT NULL);
